INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Show-LcmDaemon.ps1', 'ShowDaemon', 'LCM_Inventory', 'Desktop Bridge', 'User', 0, 1, 'PowerShell', 'Displays live telemetry, runtime status, and log tailing for the LCM Desktop REST Bridge Daemon.', 'ShowDaemon', 'LCM_Inventory\tools\Show-LcmDaemon.ps1', '[{"Name": "Port", "Type": "Int32", "Mandatory": false, "Default": "0", "Description": "Target TCP port to inspect (Default: 9876). Configurable via $env:LCM_DAEMON_PORT."}, {"Name": "Log", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Displays the recent active daemon audit log in read-only mode (Aliases: -View, -ShowLog)."}, {"Name": "Lines", "Type": "Int32", "Mandatory": false, "Default": "50", "Description": "Number of recent lines to display when viewing log (Default: 50)."}, {"Name": "Tail", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Live tails the active daemon audit log to terminal (Aliases: -Follow, -f)."}, {"Name": "Cleanup", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Triggers automated cleanup of daemon log files older than -MaxAgeDays (Aliases: -PurgeLogs)."}, {"Name": "MaxAgeDays", "Type": "Int32", "Mandatory": false, "Default": "7", "Description": "Age threshold in days for log cleanup (Default: 7)."}, {"Name": "Force", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Forces log cleanup without interactive prompt confirmation."}, {"Name": "Start", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Starts the desktop daemon in background if not already running."}, {"Name": "Stop", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Sends a shutdown signal to the active daemon."}, {"Name": "Restart", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Safely stops and restarts the background daemon."}]', '"LcmDesktopDaemon.ps1"', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Show-FailureAnalysis.ps1', 'ShowFailureAnalysis', 'LCM_Inventory', 'Session Failure Analysis', 'User', 0, 0, 'PowerShell', 'Opens a retained failure-analysis snapshot through the local LCM daemon without rerunning analysis.', 'ShowFailureAnalysis -ReportPath ''D:\reports\Catalog-of-Errors-and-Failure-Modes-20261021-220000.md''', 'LCM_Inventory\tools\Show-FailureAnalysis.ps1', '[{"Name": "ReportPath", "Type": "String", "Mandatory": false, "Default": "", "Description": "Exact retained Markdown or structured JSON report to display."}, {"Name": "SnapshotRoot", "Type": "String", "Mandatory": false, "Default": "", "Description": "Optional snapshot root; defaults to data\\artifacts\\failure-analysis."}, {"Name": "Pane", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Opens the display inside an Antigravity IDE editor/side pane"}, {"Name": "ShowAll", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Emits each structured audit record to the host. Detailed is an alias."}]', '["LcmDisplayVersion.psm1", "FailureAnalysisHtml.psm1", "LcmStandardDisplay.psm1", "Module: (Join-Path $inventoryRoot ''modules\\LcmDisplayVersion.psm1'')", "Module: (Join-Path $inventoryRoot ''modules\\FailureAnalysisHtml.psm1'')"]', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Show-LastLog.ps1', 'ShowLastLog', 'LCM_Inventory', 'Log Diagnostics', 'User', 0, 1, 'PowerShell', 'Displays the most recently updated audit log in the workspace with live tail and level filtering.', 'ShowLastLog', 'LCM_Inventory\tools\Show-LastLog.ps1', '[{"Name": "ToolName", "Type": "String", "Mandatory": false, "Default": "", "Description": "Optional filter to locate the latest log for a specific tool"}, {"Name": "Subsystem", "Type": "String", "Mandatory": false, "Default": "", "Description": "Filter logs by subsystem name (e.g. HaSSD06, LCM_Inventory, LCM)"}, {"Name": "IncludeInternal", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Includes internal plumbing and maintenance logs"}, {"Name": "NotepadPlus", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Forces opening the log directly in Notepad++ instead of default Notepad"}, {"Name": "Explorer", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Opens File Explorer selecting the log file"}, {"Name": "ExplorerOnly", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Opens File Explorer window selecting the log without launching text editor"}, {"Name": "EditorOnly", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Opens log directly in text editor without launching File Explorer"}]', '["Invoke-InteractiveDesktop.ps1", "Search-Everything.ps1", "Everything", "es.exe"]', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
