INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Invoke-LcmDo.ps1', 'do', 'LCM_Inventory', 'Execution Gateway', 'User', 0, 0, 'PowerShell', 'Dispatches commands through the LCM Desktop Daemon on port 9876 for elevated or sandbox-free user desktop execution.', 'do -Command "es.exe FolderTimeUpdate" -Sync', 'LCM_Inventory\tools\Invoke-LcmDo.ps1', '[{"Name": "Command", "Type": "String", "Mandatory": false, "Default": "", "Description": "The command line or executable path to execute."}, {"Name": "Elevated", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Executes with Administrator elevation."}, {"Name": "Sync", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Executes synchronously and returns stdout/stderr."}, {"Name": "NoExit", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Keeps spawned console window open."}, {"Name": "TimeoutSec", "Type": "Int32", "Mandatory": false, "Default": "30", "Description": "Maximum timeout in seconds for synchronous execution."}, {"Name": "Port", "Type": "Int32", "Mandatory": false, "Default": "9876", "Description": "Desktop Daemon port."}]', '["KillLogitechUpdateFull.ps1", "es.exe"]', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Show-LcmControl.ps1', 'ShowCM', 'LCM_Inventory', 'Configuration Management', 'User', 0, 0, 'PowerShell', 'Unified LCM Control Hub dashboard and proposal lifecycle manager.', 'ShowCM', 'LCM_Inventory\tools\Show-LcmControl.ps1', '[{"Name": "ReviewMode", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Open in pending visual review mode"}, {"Name": "DatesMode", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Open in CRP Lifecycle Dates modal mode"}, {"Name": "Horizon", "Type": "String", "Mandatory": false, "Default": "active", "Description": "Release horizon filter: active (default), all, or historical"}, {"Name": "LcmVersion", "Type": "String", "Mandatory": false, "Default": "", "Description": "Filter by specific LCM version (e.g. 10.2.3, 10.2.1, 10.1.0, 10.0.0)"}, {"Name": "Repo", "Type": "String", "Mandatory": false, "Default": "", "Description": "Filter by repository or subsystem"}, {"Name": "State", "Type": "String", "Mandatory": false, "Default": "", "Description": "Filter by authoritative lifecycle state (suggested, in_progress, verified, in_review, completed, pushed, held, withdrawn, rejected, superseded)"}, {"Name": "Id", "Type": "Object[]", "Mandatory": false, "Default": "", "Description": "Optional array of Proposal IDs to filter (e.g. 1, 28, 44, 164)"}, {"Name": "StateEvent", "Type": "String", "Mandatory": false, "Default": "", "Description": "Filter by state change event presence (created, in_progress, completed, pushed, deferred)"}, {"Name": "CliMode", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Output proposal dates table directly to terminal without launching desktop browser"}, {"Name": "Detail", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Displays detailed individual state transition timeline in terminal CLI mode"}, {"Name": "Lifecycle", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Open the lifecycle ledger in terminal detail mode"}, {"Name": "Pane", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Opens the Control Hub inside an Antigravity IDE editor/side pane"}, {"Name": "StartDaemon", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Compatibility switch; interactive launches automatically recover the desktop daemon when it is offline"}, {"Name": "TimerOn", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Display verbose execution timing telemetry milestones"}]', '["LcmStandardDisplay.psm1", "Module: (Join-Path $PSScriptRoot ''..\\modules\\LcmDisplayVersion.psm1'')"]', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
