INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Show-ToolsExplorer.ps1', 'ToolsExplorer', 'LCM_Inventory', 'Tool Discovery', 'User', 0, 0, 'PowerShell', 'Opens the modern interactive LCM Tool Explorer dashboard in the browser or terminal.', 'ToolsExplorer', 'LCM_Inventory\tools\Show-ToolsExplorer.ps1', '[{"Name": "Audience", "Type": "String", "Mandatory": false, "Default": "User", "Description": "Pre-filter by audience category: ''User'' (daily operations), ''Dev'' (internal plumbing), or ''All''. Defaults to ''User''."}, {"Name": "Group", "Type": "String", "Mandatory": false, "Default": "All", "Description": "Pre-filter by group or subsystem name (e.g. ''HaSSD06'', ''SystemConfiguration'', ''LCM_Inventory'', ''LCM''). Defaults to ''All''."}, {"Name": "Subsystem", "Type": "String", "Mandatory": false, "Default": "All", "Description": "Direct pre-filter for specific subsystem (e.g. ''HaSSD06'', ''LCM_AI'', ''LCM_Inventory''). Defaults to ''All''."}, {"Name": "HaSSD06", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Quick switch to filter directly to Home Assistant HaSSD06 Subsystem tools (Aliases: -Ha, -HomeAssistant)."}, {"Name": "Role", "Type": "String", "Mandatory": false, "Default": "All", "Description": "Pre-filter by functional role (e.g. ''QualityGate'', ''ReviewGate'', ''Elevation'', ''DesktopGUI''). Defaults to ''All''."}, {"Name": "Tool", "Type": "String", "Mandatory": false, "Default": "All", "Description": "Pre-select a specific tool name to highlight on startup. Defaults to ''All''."}, {"Name": "Env", "Type": "String", "Mandatory": false, "Default": "All", "Description": "Pre-filter by tool environment (''PS1'', ''CMD'', ''PY'', ''REG'', ''LNK'', ''All''). Defaults to ''All''."}, {"Name": "Filter", "Type": "String", "Mandatory": false, "Default": "", "Description": "Initial search keyword to apply on dashboard startup. Defaults to ''''."}, {"Name": "Lifecycle", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Pre-filters the catalog for proposal lifecycle, review, and push tooling."}, {"Name": "NoBrowser", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Suppresses launching the web browser and outputs the tool catalog directly as formatted text in the terminal (Aliases: -Cli, -Text, -Console)."}, {"Name": "Pane", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Opens the dashboard inside an Antigravity IDE editor/side pane"}]', '["LCM_Context.psm1", "Invoke-LcmProtocol.ps1", "LcmToolCatalog.psm1", "LcmStandardDisplay.psm1", "Module: (Join-Path $PSScriptRoot ''..\\modules\\LcmDisplayVersion.psm1'')"]', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
