INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Invoke-MacriumBcrReview.ps1', 'BCR', 'LCM_Inventory', 'Proposal Review', 'User', 0, 0, 'PowerShell', 'Opens the exact CRP/BUG Macrium BCR review using writable baseline and AutoHotkey (AHK) UI automation with _LCM Beyond Compare profile.', 'BCR -CRP CRP-284 -RepositoryName LCM_Inventory', 'LCM_Inventory\tools\Invoke-MacriumBcrReview.ps1', '[{"Name": "CRP", "Type": "String", "Mandatory": false, "Default": "", "Description": "Identifier of the CRP or BUG proposal under review (e.g. CRP-309)."}, {"Name": "RepositoryName", "Type": "String", "Mandatory": false, "Default": "LCM_Inventory", "Description": "Target repository containing the review changes (Default: LCM_Inventory)."}, {"Name": "BaseCommit", "Type": "String", "Mandatory": false, "Default": "HEAD", "Description": "Base commit to compare against (Default: HEAD)."}, {"Name": "LifecycleManaged", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Indicates the invocation is dispatched through proposal lifecycle gating."}, {"Name": "NewBaseline", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Forces unmounting and remounting a fresh Macrium baseline image."}, {"Name": "CandidateDrives", "Type": "Object", "Mandatory": false, "Default": "@(''F'', ''G'', ''H'', ''I'')", "Description": "Acceptable drive letters for mounting baseline partition (Default: F, G, H, I)."}, {"Name": "MountTimeoutSeconds", "Type": "Int32", "Mandatory": false, "Default": "120", "Description": "Timeout in seconds for drive mount operations (Default: 120)."}]', '["ProposalManager.psm1", "Invoke-MacriumDailyBcrBaseline.ps1"]', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Show-Actions.ps1', 'ShowActions', 'LCM_Inventory', 'Audit Logs', 'User', 0, 0, 'PowerShell', 'Fast lightweight terminal reader displaying recent operational actions and tool execution step summaries.', 'ShowActions', 'LCM_Inventory\tools\Show-Actions.ps1', '[{"Name": "Count", "Type": "Int32", "Mandatory": false, "Default": "5", "Description": "Number of recent actions to display (Default: 5)."}, {"Name": "Subsystem", "Type": "String", "Mandatory": false, "Default": "", "Description": "Filters action log stream by specific subsystem (e.g. ''HaSSD06'')."}, {"Name": "Detailed", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Displays all raw log lines for the action instead of the compact step summary."}, {"Name": "ToolName", "Type": "String", "Mandatory": false, "Default": "", "Description": "Filter by a specific tool name (e.g. ''Show-ToolIndex'', ''Update-ToolCatalog'', ''Export-LCMRules'')."}, {"Name": "Open", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Opens the latest action log in Notepad on Session 1 interactive desktop."}]', '"Invoke-InteractiveDesktop.ps1"', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Search-Everything.ps1', 'SearchEverything', 'LCM_Inventory', 'File Search', 'User', 0, 1, 'PowerShell', 'CLI search interface utilizing Voidtools Everything command line utility (es.exe).', 'SearchEverything', 'LCM_Inventory\tools\Search-Everything.ps1', '[{"Name": "Query", "Type": "String", "Mandatory": false, "Default": "", "Description": "Search term or pattern for filenames and paths"}, {"Name": "Content", "Type": "String", "Mandatory": false, "Default": "", "Description": "Search term for full-text content indexing (uses content: filter)"}, {"Name": "Path", "Type": "String", "Mandatory": false, "Default": "", "Description": "Restrict search scope to a specific directory or drive (e.g. D:\\Git_Repositories)"}, {"Name": "Extension", "Type": "String", "Mandatory": false, "Default": "", "Description": "Filter results by file extension (e.g. ps1, md, json)"}, {"Name": "Regex", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Enable regular expression matching"}, {"Name": "MaxResults", "Type": "Int32", "Mandatory": false, "Default": "50", "Description": "Maximum number of search results to return (default: 50)"}, {"Name": "CaseSensitive", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Enable case-sensitive search"}, {"Name": "Port", "Type": "Int32", "Mandatory": false, "Default": "8080", "Description": "HTTP Server port for Everything 1.5a REST API (default: 8080)"}, {"Name": "Raw", "Type": "String", "Mandatory": true, "Default": "", "Description": "Pass raw search query string directly to Everything"}]', '["Invoke-LcmDo.ps1", "Everything", "es.exe", "EVERYTHING"]', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('LcmDesktopDaemon.ps1', 'LcmDaemon', 'LCM_Inventory', 'Desktop Bridge', 'Developer', 1, 1, 'PowerShell', 'Lightweight high-performance HTTP/REST bridge daemon running in Session 1 for cross-session GUI dispatch.', 'LcmDaemon', 'LCM_Inventory\tools\LcmDesktopDaemon.ps1', '[{"Name": "Port", "Type": "Int32", "Mandatory": false, "Default": "0", "Description": "The local TCP listening port (Default: 9876). Configurable via parameter or $env:LCM_DAEMON_PORT."}, {"Name": "Status", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Queries and displays the active status of the local desktop daemon without starting a new instance."}, {"Name": "Stop", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Sends a shutdown signal to the running desktop daemon instance."}, {"Name": "Background", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Spawns the daemon in a hidden, detached background process."}, {"Name": "MaxLogAgeDays", "Type": "Int32", "Mandatory": false, "Default": "7", "Description": "Maximum age in days before daemon log files are automatically pruned (Default: 7)."}]', '["DaemonDto.ps1", "LcmTokenVault.ps1", "LcmSecurityGateway.ps1", "DaemonEnvironment.ps1", "DaemonActionController.ps1", "LcmDisplayHttp.psm1", "Remove-LcmShortName.ps1", "Module: (Join-Path $lcdRoot ''modules\\LcmDisplayHttp.psm1'')"]', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Register-LcmDesktopDaemon.ps1', 'RegisterDaemon', 'LCM_Inventory', 'Desktop Bridge', 'Developer', 1, 1, 'PowerShell', 'Registers the persistent LCM Desktop REST Bridge Daemon in Task Scheduler with automatic startup.', 'RegisterDaemon', 'LCM_Inventory\tools\Register-LcmDesktopDaemon.ps1', '[{"Name": "Install", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Installs the user scheduled task for automatic launch at user logon."}, {"Name": "Uninstall", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Removes user startup hooks and scheduled tasks."}, {"Name": "Status", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Displays active installation and daemon runtime status."}, {"Name": "Start", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Starts the desktop daemon immediately in the background."}, {"Name": "Stop", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Stops the running desktop daemon."}, {"Name": "Port", "Type": "Int32", "Mandatory": false, "Default": "9876", "Description": "Configures the target port (Default: 9876)."}]', '"LcmDesktopDaemon.ps1"', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Show-ToolIndex.ps1', 'ShowToolIndex', 'LCM_Inventory', 'Tool Discovery', 'Developer', 0, 0, 'PowerShell', 'Underlying generation engine for the interactive LCM Tool Explorer HTML application.', 'ShowToolIndex', 'LCM_Inventory\tools\Show-ToolIndex.ps1', '[{"Name": "Audience", "Type": "String", "Mandatory": false, "Default": "User", "Description": "Pre-filter by audience category: ''User'', ''Dev'', or ''All'' (default: User)"}, {"Name": "Group", "Type": "String", "Mandatory": false, "Default": "All", "Description": "Pre-filter by group or repository name (default: All)"}, {"Name": "Subsystem", "Type": "String", "Mandatory": false, "Default": "All", "Description": "Direct pre-filter for specific subsystem (default: All)"}, {"Name": "HaSSD06", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Quick switch to filter directly to Home Assistant HaSSD06 tools"}, {"Name": "Role", "Type": "String", "Mandatory": false, "Default": "All", "Description": "Pre-filter by functional role (default: All)"}, {"Name": "Tool", "Type": "String", "Mandatory": false, "Default": "All", "Description": "Pre-select a specific tool name to highlight on startup (default: All)"}, {"Name": "Env", "Type": "String", "Mandatory": false, "Default": "All", "Description": "Pre-filter by tool environment: ''PS1'', ''CMD'', ''PY'', ''REG'', ''LNK'', ''All"}, {"Name": "Filter", "Type": "String", "Mandatory": false, "Default": "", "Description": "Initial search keyword or !term query to apply on dashboard startup"}, {"Name": "NoBrowser", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Outputs tool catalog directly as formatted text in terminal without launching browser"}, {"Name": "All", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Display all tools without audience filtering"}, {"Name": "User", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Filter to User-facing operational tools"}, {"Name": "Dev", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Filter to Developer / maintenance tools"}]', '"Show-Tools.ps1"', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Invoke-LcmDisplayRender.ps1', 'RenderLcmDisplay', 'LCM_Inventory', 'Internal Display Infrastructure', 'Developer', 0, 0, 'PowerShell', 'Internal allowlisted renderer for verified Standard Display publication; not a user-facing display launcher.', 'RenderLcmDisplay', 'LCM_Inventory\tools\Invoke-LcmDisplayRender.ps1', '[{"Name": "DisplayId", "Type": "String", "Mandatory": false, "Default": "", "Description": ""}, {"Name": "LogPath", "Type": "String", "Mandatory": false, "Default": "", "Description": ""}, {"Name": "ShowAll", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": ""}]', '["LcmDisplayDependencies.psm1", "Update-ToolCatalog.ps1", "Module: (Join-Path $root ''modules\\LcmDisplayDependencies.psm1'')"]', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Invoke-MacriumDailyBcrBaseline.ps1', 'MacriumDailyBcrBaseline', 'LCM_Inventory', 'Beyond Compare Review', 'Developer', 0, 0, 'PowerShell', 'Prepares today Macrium Reflect image as writable Beyond Compare baseline with AutoHotkey (AHK) UI automation.', 'MacriumDailyBcrBaseline', 'LCM_Inventory\tools\Invoke-MacriumDailyBcrBaseline.ps1', '[{"Name": "BackupDefinitionPath", "Type": "String", "Mandatory": false, "Default": "D:\\OneDrive\\Documents\\Reflect\\@B_D4P3+4-WDB850-AD.xml", "Description": "Path to the Macrium Reflect XML backup definition file to monitor or execute."}, {"Name": "BackupDirectory", "Type": "String", "Mandatory": false, "Default": "B:\\Backups\\D4P3+4-WDB850-AD", "Description": "Directory containing the completed Macrium .mrimgx backup images."}, {"Name": "ExpectedVolumeLabel", "Type": "String", "Mandatory": false, "Default": "D4P3-WDB850-D", "Description": "Expected volume label for the mounted baseline partition (default: D4P3-WDB850-D)."}, {"Name": "CandidateDrives", "Type": "Object", "Mandatory": false, "Default": "@(''F'', ''G'', ''H'', ''I'')", "Description": "List or delimited string of acceptable drive letters (length >= 1)"}, {"Name": "PollSeconds", "Type": "Int32", "Mandatory": false, "Default": "60", "Description": "Polling interval in seconds when awaiting Macrium backup completion."}, {"Name": "TimeoutMinutes", "Type": "Int32", "Mandatory": false, "Default": "240", "Description": "Maximum wait time in minutes before timing out an in-progress Macrium backup."}, {"Name": "MountTimeoutSeconds", "Type": "Int32", "Mandatory": false, "Default": "120", "Description": "Timeout in seconds for drive mount dialog interaction and volume appearance."}, {"Name": "ReviewScope", "Type": "String", "Mandatory": false, "Default": "", "Description": "Active CRP or BUG identifier to associate with the Beyond Compare window title."}, {"Name": "StartBackupIfMissing", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Automatically initiates the configured backup definition if today''s image is not found."}, {"Name": "ForceNewBackup", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Forces execution of a fresh Macrium backup definition regardless of same-day images."}, {"Name": "NewBaseline", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Forces unmounting existing baselines and mounting a new Macrium image (fast-path is default)."}, {"Name": "NoLaunchReview", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Mounts the baseline image and sets registry telemetry without opening Beyond Compare."}, {"Name": "ElevatedWorker", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Internal switch executed under administrative elevation to perform drive mounting."}, {"Name": "ReceiptPath", "Type": "String", "Mandatory": false, "Default": "", "Description": "Temporary JSON receipt path used by the elevated worker process."}, {"Name": "ImagePath", "Type": "String", "Mandatory": false, "Default": "", "Description": "Explicit path to the .mrimgx image to mount when executing as the elevated worker."}]', '["LcmAhkAtoms.psm1", "bcompare", "BCompare.exe", "BCompare"]', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Absorb-LcmContextRemark.ps1', 'AbsorbLcmContextRemark', 'LCM_Inventory', 'Utility', 'Developer', 0, 1, 'PowerShell', 'Absorb-LcmContextRemark execution tool.', 'AbsorbLcmContextRemark', 'LCM_Inventory\tools\Absorb-LcmContextRemark.ps1', '[{"Name": "Id", "Type": "String", "Mandatory": true, "Default": "", "Description": "Proposal ID number (e.g. 280, 267) or CRP identifier (e.g. CRP-280, BUG-311)."}, {"Name": "TextMatch", "Type": "String", "Mandatory": true, "Default": "", "Description": "Substring or regex pattern matching the operator remark in ACTIVE_CONTEXT.md to absorb."}, {"Name": "DryRun", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Previews absorption and removal without modifying ACTIVE_CONTEXT.md or the proposal specification."}, {"Name": "CheckOnly", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Performs contradiction analysis between the remark and the target CRP specification without mutating files."}]', '"ProposalManager.psm1"', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
