INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Archive-Clean.ps1', 'ArchiveClean', 'LCM_Inventory', 'Utility', 'Developer', 0, 1, 'PowerShell', 'Archive-Clean execution tool.', 'ArchiveClean', 'LCM_Inventory\tools\Archive-Clean.ps1', '[{"Name": "Older", "Type": "String", "Mandatory": false, "Default": "1m", "Description": "Age threshold for archived conversations to delete. Default is ''1m'' (older than 1 month). Supported units: d (days), w (weeks), m (months), y (years), h (hours). Examples: ''3d'', ''2w'', ''1m'', ''6m''."}, {"Name": "AntigravityDir", "Type": "String", "Mandatory": false, "Default": "", "Description": "Path to the Antigravity data directory. Defaults to $env:USERPROFILE\\.gemini\\antigravity."}, {"Name": "DryRun", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Simulates execution without deleting files or records."}, {"Name": "Force", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Bypasses the interactive confirmation prompt before deletion."}, {"Name": "ShowAll", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Displays detailed information for each evaluated archived conversation."}]', '"Python 3.x (with built-in sqlite3)"', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
