INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Create-LcmTool.ps1', 'CreateTool', 'LCM_Inventory', 'Tool Scaffolding', 'Developer', 1, 1, 'PowerShell', 'Scaffolds new LCM PowerShell tools, derives short names, and generates trampolines in LCM_Inventory/Cmd/.', 'CreateTool', 'LCM_Inventory\tools\Create-LcmTool.ps1', '[{"Name": "Name", "Type": "String", "Mandatory": false, "Default": "", "Description": "The canonical tool file name or base name (e.g. ''Test-NetworkAdapter.ps1'' or ''Test-NetworkAdapter'')."}, {"Name": "ShortName", "Type": "String", "Mandatory": false, "Default": "", "Description": "Optional custom short-name command alias. If omitted, derived from the taxonomy rules."}, {"Name": "Subsystem", "Type": "String", "Mandatory": false, "Default": "LCM", "Description": "The target subsystem or group (e.g. ''SystemConfiguration'', ''HaSSD06'', ''LCM'', ''BackgroundModifier'', ''LCM_Inventory'', ''LCM_AI''). Defaults to ''LCM''."}, {"Name": "Role", "Type": "String", "Mandatory": false, "Default": "Diagnostics", "Description": "The functional lifecycle archetype: ''Invariants'', ''Customization'', ''Repair'', ''Diagnostics'', ''Telemetry'', ''Recovery'', ''ToolManagement'', ''QualityGate'', ''ReviewCommit'', ''GUI'', ''Elevation'', ''Utility''."}, {"Name": "Category", "Type": "String", "Mandatory": false, "Default": "General", "Description": "The component or domain category (e.g. ''Hardware Stability'', ''Network Diagnostics'', ''Registry Tweaks'', ''Windows Setup'')."}, {"Name": "Audience", "Type": "String", "Mandatory": false, "Default": "User", "Description": "The target audience persona: ''User'' (Operator) or ''Developer'' (Plumbing). Defaults to ''User''."}, {"Name": "Admin", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Indicates that execution requires Administrator elevation."}, {"Name": "NoExit", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Forces the terminal console to remain open after completion (Defaults to true for interactive/diagnostic/admin tools)."}, {"Name": "Description", "Type": "String", "Mandatory": false, "Default": "", "Description": "A concise 1-2 sentence description of the tool''s purpose and functionality."}, {"Name": "Force", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Overwrites existing tool files if present."}]', '["None", "Test-NetworkAdapter.ps1", "Update-ToolCatalog.ps1"]', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
