INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Invoke-ProposalAction.ps1', 'ProposalAction', 'LCM_Inventory', 'Utility', 'Developer', 0, 1, 'PowerShell', 'Invoke-ProposalAction execution tool.', 'ProposalAction', 'LCM_Inventory\tools\Invoke-ProposalAction.ps1', '[{"Name": "Action", "Type": "String", "Mandatory": false, "Default": "list", "Description": "Action to perform on proposals or governance settings"}, {"Name": "TargetExpression", "Type": "String", "Mandatory": false, "Default": "", "Description": "Target proposal expression (e.g. all, #1, 105, 100-105)"}, {"Name": "Title", "Type": "String", "Mandatory": false, "Default": "", "Description": "New title when executing action rename or title"}, {"Name": "ProposalId", "Type": "Int32", "Mandatory": false, "Default": "", "Description": "Explicit Gate-1-accepted proposal ID required for structural App creation"}, {"Name": "Details", "Type": "String", "Mandatory": false, "Default": "", "Description": "Additional details or notes for proposal transition"}, {"Name": "Changes", "Type": "String", "Mandatory": false, "Default": "", "Description": "Concrete correction requests for reinstate; when omitted, reinstate returns the CRP to suggested"}, {"Name": "State", "Type": "String", "Mandatory": false, "Default": "", "Description": "Target plan state to set (bug, suggested, approved, deferred, rejected, completed, pushed, held)"}, {"Name": "ProgressState", "Type": "String", "Mandatory": false, "Default": "", "Description": "Target implementation progress state to set"}, {"Name": "Priority", "Type": "String", "Mandatory": false, "Default": "", "Description": "Priority level to assign (C=Critical, H=High, M=Medium, L=Low, D=Deferred)"}, {"Name": "TargetRepo", "Type": "String", "Mandatory": false, "Default": "", "Description": "Target repository for child regression proposal or App context"}, {"Name": "Reason", "Type": "String", "Mandatory": false, "Default": "", "Description": "Reason or trigger description for child regression proposal"}, {"Name": "MaxRegressionDepth", "Type": "Int32", "Mandatory": false, "Default": "2", "Description": "Max regression depth limit (default: 2)"}, {"Name": "Granularity", "Type": "String", "Mandatory": false, "Default": "", "Description": "Set review granularity: coarse (single BC5 review) or tight (BC5 review per proposal)"}, {"Name": "Mode", "Type": "String", "Mandatory": false, "Default": "", "Description": "Set LCM governance mode: active (proposal-first) or paused"}, {"Name": "TestingMode", "Type": "String", "Mandatory": false, "Default": "", "Description": "Set LCM testing mode: active (syntax/unit) or paused (deferred deep testing)"}, {"Name": "SwitchState", "Type": "String", "Mandatory": false, "Default": "", "Description": "Set a workspace switch to active or paused"}, {"Name": "MinimalTests", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Single-cycle minimal testing scope: fast syntax and AST validation only"}, {"Name": "Force", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Authorized exception to interactive visual-review confirmation only; does not waive lifecycle or preflight checks"}, {"Name": "Immediately", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Emergency quality-check deferral; a single CRP target is reclassified as BUG, while a multi-target cohort requires a BUG; requires -Details and ends at BCR"}, {"Name": "Preview", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Resolve and report the BCR cohort without launching review or changing lifecycle state"}, {"Name": "BaseCommit", "Type": "String", "Mandatory": false, "Default": "HEAD", "Description": "Baseline commit used for BCR cohort review"}, {"Name": "CohortAction", "Type": "String", "Mandatory": false, "Default": "", "Description": "Cohort action: create, add, remove, hold, reopen, or close"}, {"Name": "CohortId", "Type": "String", "Mandatory": false, "Default": "", "Description": "Declared cohort ID (COH-<prime proposal ID>)"}, {"Name": "SuccessorId", "Type": "Int32", "Mandatory": false, "Default": "0", "Description": "Successor proposal ID required by the supersede action"}, {"Name": "IncludeUnreviewed", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Include unreviewed live paths during cohort completion"}, {"Name": "ReviewObligationId", "Type": "String", "Mandatory": false, "Default": "", "Description": "Persisted cross-repository review-obligation ledger entry to satisfy through the normal BCR action"}]', '["sync_proposals_db.py", "Invoke-MacriumBcrReview.ps1", "Complete-ReviewCohort.ps1", "Submit-ReviewResult.ps1"]', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
