INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Start-MacriumDailyBackup.ps1', 'StartMacriumDailyBackup', 'LCM_Inventory', 'Utility', 'Developer', 1, 1, 'PowerShell', 'Start-MacriumDailyBackup execution tool.', 'StartMacriumDailyBackup', 'LCM_Inventory\tools\Start-MacriumDailyBackup.ps1', '[{"Name": "Mount", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Mounts the newly created backup image as the writable BCR baseline partition upon completion."}, {"Name": "ForceNewBackup", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Forces execution of a fresh backup definition even if a completed image exists for today."}, {"Name": "ReviewScope", "Type": "String", "Mandatory": false, "Default": "", "Description": "Active CRP or BUG identifier to associate with the Beyond Compare window title if -Mount is set."}, {"Name": "CandidateDrives", "Type": "Object", "Mandatory": false, "Default": "@(''F'', ''G'', ''H'', ''I'')", "Description": "List or delimited string of acceptable drive letters for mounting (Default: F;G;H;I)."}, {"Name": "NoLaunchReview", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "When -Mount is set, mounts the baseline and records registry telemetry without opening Beyond Compare."}, {"Name": "BackupDefinitionPath", "Type": "String", "Mandatory": false, "Default": "D:\\OneDrive\\Documents\\Reflect\\@B_D4P3+4-WDB850-AD.xml", "Description": "Path to the Macrium Reflect backup definition XML file."}, {"Name": "BackupDirectory", "Type": "String", "Mandatory": false, "Default": "B:\\Backups\\D4P3+4-WDB850-AD", "Description": "Path to the directory containing completed .mrimgx backup images."}, {"Name": "PollSeconds", "Type": "Int32", "Mandatory": false, "Default": "5", "Description": "Interval in seconds between completion polls (Default: 5)."}, {"Name": "TimeoutMinutes", "Type": "Int32", "Mandatory": false, "Default": "45", "Description": "Maximum wait time in minutes for backup completion (Default: 45)."}, {"Name": "MountTimeoutSeconds", "Type": "Int32", "Mandatory": false, "Default": "120", "Description": "Timeout in seconds for drive mount dialog interaction and volume appearance (Default: 120)."}]', '["Set-LcmMachineRegistry.ps1", "Mount-MacriumLatestBaseline.ps1"]', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
