s for Add or Update operations."}]', 'null', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Sync-LcmModuleVersions.ps1', 'SyncLcmModuleVersions', 'LCM_Inventory', 'Utility', 'Developer', 0, 1, 'PowerShell', 'Sync-LcmModuleVersions execution tool.', 'SyncLcmModuleVersions', 'LCM_Inventory\tools\Sync-LcmModuleVersions.ps1', '[{"Name": "TargetMajor", "Type": "Int32", "Mandatory": false, "Default": "10", "Description": "Target major release number to enforce (e.g. 10)"}, {"Name": "TargetBaseline", "Type": "String", "Mandatory": false, "Default": "10.0.0", "Description": "Target active release baseline version string (e.g. 10.0.0)"}, {"Name": "Apply", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Apply live version string mutations to documentation and manifests"}, {"Name": "AuditOnly", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Perform audit only without writing any file changes (default read-only)"}, {"Name": "RootPath", "Type": "String", "Mandatory": false, "Default": "D:\\Git_Repositories", "Description": "Root workspace directory containing repository manifests"}, {"Name": "FullBaseline", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Normalize all LCM-owned semantic versions to TargetBaseline and metadata dates to the release date."}]', 'null', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('Sync-LcmProposalsDb.ps1', 'SyncLcmProposalsDb', 'LCM_Inventory', 'Utility', 'Developer', 0, 1, 'PowerShell', 'Sync-LcmProposalsDb execution tool.', 'SyncLcmProposalsDb', 'LCM_Inventory\tools\Sync-LcmProposalsDb.ps1', '[{"Name": "Action", "Type": "String", "Mandatory": false, "Default": "Sync", "Description": "Operation to perform: - ''Sync'' : JSON -> SQLite DB + SQL text dump (default). - ''Dump'' : SQLite DB -> Canonical proposals.sql text dump. - ''Hydrate'' : Reconstructs SQLite DB from canonical proposals.sql text dump. - ''Verify'' : 3-way parity check across JSON, SQLite DB, and SQL text dump. - ''Query'' : High-speed query returning objects from SQLite. - ''InstallHooks'' : Installs Git post-merge and post-checkout hooks for automatic hydration on pull/checkout."}, {"Name": "Horizon", "Type": "String", "Mandatory": false, "Default": "", "Description": "Release horizon filter for querying: ''active'' (hides published historical releases < 10.2.0), ''historical'' (only historical releases), or ''all'' (all 296+ proposals)."}, {"Name": "Version", "Type": "String", "Mandatory": false, "Default": "", "Description": "Specific LCM version to filter by (e.g. ''10.2.3'', ''10.2.x'', ''10.1.0'', ''10.0.0'', ''Legacy (<10.0)'')."}, {"Name": "State", "Type": "String", "Mandatory": false, "Default": "", "Description": "Specific proposal lifecycle state to filter by (e.g. ''in_progress'', ''pushed'', ''held'')."}, {"Name": "ActiveOnly", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Filters only active/open proposals (excluding terminal pushed, rejected, superseded, withdrawn)."}, {"Name": "WorkspaceRole", "Type": "String", "Mandatory": false, "Default": "LIVE", "Description": "Context role for database metadata: ''LIVE'' (default), ''SANDBOX'', or ''BASELINE_ARCHIVE''."}, {"Name": "SandboxId", "Type": "String", "Mandatory": false, "Default": "", "Description": "Sandbox identifier when executing within an isolated sandbox (e.g. ''SBX-01'')."}, {"Name": "DatabasePath", "Type": "String", "Mandatory": false, "Default": "", "Description": "Custom path to SQLite database. Defaults to LCM_Inventory/data/proposals/proposals.db."}, {"Name": "JsonPath", "Type": "String", "Mandatory": false, "Default": "", "Description": "Custom path to JSON proposals ledger. Defaults to LCM_Inventory/data/proposals/proposals.json."}, {"Name": "SqlPath", "Type": "String", "Mandatory": false, "Default": "", "Description": "Custom path to canonical SQL dump. Defaults to LCM_Inventory/data/proposals/proposals.sql."}, {"Name": "Silent", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Suppresses informational console banners."}]', '"sync_proposals_db.py"', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
