INSERT INTO tools (name, short_name, subsystem, category, audience, admin, no_exit, type, description, example, relative_path, parameters_json, dependencies_json, created_at, updated_at) VALUES ('@Repair_Diagnose-OneDriveSync.ps1', '@RepairDiagnoseOneDriveSync', 'LCM_Tools', 'Utility', 'Developer', 1, 1, 'PowerShell', '@Repair_Diagnose-OneDriveSync execution tool.', '@RepairDiagnoseOneDriveSync', 'LCM_Inventory\tools\@Repair_Diagnose-OneDriveSync.ps1', '[{"Name": "FixAcl", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Repairs ownership and sets AuthorizeMasterUser ACLs on all inaccessible OneDrive target folders."}, {"Name": "Reconcile", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Flips stuck 0-byte download items (fileStatus=3) to Synced (fileStatus=2) and resets postponed change locks."}, {"Name": "Reset", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Executes official Microsoft OneDrive cache reset and explicitly restarts the OneDrive tray process."}, {"Name": "PurgeGhosts", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Purges stale 0-byte ghost download intents from SQLite sync database by generating local placeholders."}, {"Name": "All", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Performs full automated repair: ACL fix, database reconciliation, ghost purge, and non-elevated restart."}, {"Name": "ShowAll", "Type": "SwitchParameter", "Mandatory": false, "Default": "", "Description": "Displays full detailed diagnostic flow, database table stats, postponed changes, and path evaluations."}]', '["od_diag_runner.py", "od_reconcile_runner.py"]', '2026-11-13 15:41:21', '2026-11-13 15:41:21');
